import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"中文控制台","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/chinese-console.md","filePath":"zh/manual/chinese-console.md"}'),o={name:"zh/manual/chinese-console.md"};function i(l,e,d,c,h,r){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="中文控制台" tabindex="-1">中文控制台 <a class="header-anchor" href="#中文控制台" aria-label="Permalink to &quot;中文控制台&quot;">​</a></h1><h2 id="切换" tabindex="-1">切换 <a class="header-anchor" href="#切换" aria-label="Permalink to &quot;切换&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lang zh        everything user-facing switches, live:</span></span>
<span class="line"><span>                    shell help, all 8 wizard apps, service surfaces</span></span>
<span class="line"><span>ush&gt; lang en        back to English</span></span>
<span class="line"><span>ush&gt; lang           show the current language</span></span></code></pre></div><p>locale 按调用探测（不在首次渲染时缓存），因此在长时间运行的 ush 中执行 <code>lang zh</code> 会立即影响下一行帮助输出——包括在发起切换的那个 shell 里。</p><h2 id="哪些内容被翻译" tabindex="-1">哪些内容被翻译 <a class="header-anchor" href="#哪些内容被翻译" aria-label="Permalink to &quot;哪些内容被翻译&quot;">​</a></h2><table tabindex="0"><thead><tr><th>界面</th><th>机制</th></tr></thead><tbody><tr><td>ush 内置命令</td><td>按应用的 i18n 表（<code>tr_()</code>）</td></tr><tr><td>8 个大应用</td><td>按应用的 i18n 表——菜单、提示、判定</td></tr><tr><td>约 280 个经典应用</td><td>按应用的 i18n 表（<code>_hint</code> + 正文串）</td></tr><tr><td>L0 服务行（help -w 组名、注册表标题）</td><td>l0 表（<code>etc/i18n/l0/{en,zh}.json</code>）</td></tr></tbody></table><p>缺失的翻译会回退到英文，再回退到键本身——未翻译的应用绝不会崩溃或打印乱码；它显示键本身，让缺口可见、可修复。</p><h2 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to &quot;渲染&quot;">​</a></h2><p>CJK 管线始终编译在内：16x16 GB2312 点阵字体、GBK/UTF-8 解码链，以及控制台渲染器。串口和帧缓冲控制台都能渲染中文；串口编码遵循 <code>serial_encoding</code>（默认 <code>utf8</code>，可切换为 <code>gbk</code>）。</p><h2 id="输入——输入法-ime" tabindex="-1">输入——输入法（IME） <a class="header-anchor" href="#输入——输入法-ime" aria-label="Permalink to &quot;输入——输入法（IME）&quot;">​</a></h2><p>输入法把拼音组合为 GB2312 的 16-55 区（一级字库：3755 个常用汉字），并提供词组补全：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; ime             (IME status: level-1 chars, phrases)</span></span>
<span class="line"><span>ush&gt; ime -i          (interactive compose session)</span></span></code></pre></div><p>组合会话内：输入拼音，选择候选，ESC 取消。显示服务通过 L1SVC 把同一引擎暴露给程序（IME begin / key / end 操作）。</p><h2 id="ascii-契约" tabindex="-1">ASCII 契约 <a class="header-anchor" href="#ascii-契约" aria-label="Permalink to &quot;ASCII 契约&quot;">​</a></h2><p>程序<em>名称</em>、文件路径和服务级的<strong>输出行是 ASCII 英文</strong>——它们是面向脚本的契约（向导和测试会探测这些行：<code>&quot;A/B disk: present&quot;</code>、<code>&quot;New version available.&quot;</code>）。中文是面向<em>人</em>的呈现；脚本和探测在每个 locale 下都保持稳定的英文界面。</p>`,15)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
